begin; select no_plan();
insert into public.profiles(id) values('00000000-0000-4000-8000-000000001627'),('00000000-0000-4000-8000-000000001628'),('00000000-0000-4000-8000-000000001630');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001627','owner','grant','test:admin','Admin r1','test:r1',null);
create temporary table creator_probe as select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','create_creator','{"name":"Carlos GT","email":"carlos@example.invalid","code":"CARLOSGT"}','sandbox') result;
select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','activate_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe),'discount_id','discount-test'),'sandbox');
select lives_ok($$select public.native_admin_record_payment('sandbox','{"payment_id":"order-1","account_id":"00000000-0000-4000-8000-000000001628","subscription_id":"sub-1","product":"Pro mensual","paid_at":"2026-08-01T00:00:00Z","amount_cents":319,"currency":"eur","discount_id":"discount-test","modified_at":"2026-08-01T00:00:00Z","refunded_cents":0}')$$,'pago atribuido del servidor');
select lives_ok($$select public.native_admin_record_payment('sandbox','{"payment_id":"order-2","account_id":"00000000-0000-4000-8000-000000001628","subscription_id":"sub-1","product":"Pro mensual","paid_at":"2026-09-01T00:00:00Z","amount_cents":319,"currency":"eur","modified_at":"2026-09-01T00:00:00Z","refunded_cents":0}')$$,'renovación conserva primer código');
select is(public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','get_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe)),'sandbox')->'creator'->>'earned_cents','128','319 × 30% y 319 × 10%, half-up por línea');
select lives_ok(format($$select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','record_creator_payout',%L,'sandbox')$$,jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe),'amount_cents',96)::text),'apunta pago sin mover dinero');
select is(public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','get_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe)),'sandbox')->'creator'->>'owed_cents','32','resta pago manual del saldo');
select throws_ok(format($$select public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','record_creator_payout',%L,'sandbox')$$,jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe),'amount_cents',33)::text),'55000','native_admin_owner_conflict','no paga más del saldo');
select public.native_admin_record_payment('sandbox','{"payment_id":"order-1","account_id":"00000000-0000-4000-8000-000000001628","subscription_id":"sub-1","product":"Pro mensual","paid_at":"2026-08-01T00:00:00Z","amount_cents":319,"currency":"eur","discount_id":"discount-test","modified_at":"2026-10-01T00:00:00Z","refunded_cents":319}');
select is(public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','get_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe)),'sandbox')->'creator'->>'earned_cents','128','reembolso posterior no reclama la comisión liquidada');
select lives_ok($$select public.native_admin_record_refund('sandbox','{"refund_id":"refund-before-order","payment_id":"order-3","amount_cents":319,"currency":"eur","status":"pending","modified_at":"2026-09-01T00:00:00Z"}')$$,'guarda reembolso pendiente antes de recibir la orden');
select public.native_admin_record_payment('sandbox','{"payment_id":"order-3","account_id":"00000000-0000-4000-8000-000000001630","subscription_id":"sub-3","product":"Pro anual","paid_at":"2026-09-01T00:00:00Z","amount_cents":319,"currency":"eur","discount_id":"discount-test","modified_at":"2026-09-01T00:00:00Z","refunded_cents":0}');
select is(public.native_admin_execute('00000000-0000-4000-8000-000000001627','https://clerk.admin.test','get_creator',jsonb_build_object('creator_id',(select result->'creator'->>'creator_id' from creator_probe)),'sandbox')->'creator'->>'earned_cents','128','no liquida un reembolso pendiente');
select * from finish(); rollback;
